/* MobEcodMapper.selectOrderDetail2 : 출고처리 조회 */ SELECT TOP 1 od.OD_JOB_NO
,od.HBL_NO
,od.PIECES ,od.GWT
,odAdd.CARRYIN_DATE ,CASE WHEN pod.POD_STATUS = 'ECM280' THEN 'Y' ELSE 'N' END AS CARRYOUT_YN ,CASE WHEN (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0 THEN 'Y' ELSE 'N' END AS HOLD_YN
FROM TB_ECM_OD od LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO LEFT OUTER JOIN TB_ECM_POD_03 pod ON od.OD_JOB_NO = pod.OD_JOB_NO AND pod.POD_STATUS = 'ECM280' WHERE od.ENT_CODE = #{entCode} AND od.HBL_NO = LTRIM(RTRIM(#{hblNo})) AND od.DEST_CODE = #{destCode}
AND od.PIECES > 0 AND (od.CD_TYPE = 'N' OR od.CD_TYPE = 'B' OR odAdd.DROP_YN = 'Y') AND odAdd.CARRYIN_DATE IS NOT NULL AND odAdd.CLEARANCE_DATE IS NOT NULL
AND odAdd.WH_CARRYOUT_DATE IS NULL AND odAdd.CARRYOUT_USER_ID IS NULL
AND odAdd.WH_CARRYOUT_DATE IS NOT NULL AND odAdd.CARRYOUT_USER_ID IS NOT NULL
AND od.AR_DATE >= #{srchStartDate}
AND od.AR_DATE <= #{srchEndDate}
ORDER BY od.PO_DATE DESC

