/* MobEcodMapper.carryoutSave : 모바일 출고처리 */ UPDATE TB_ECM_OD_ADDITIONAL SET
CARRYOUT_STATUS = 'F' ,WH_CARRYOUT_DATE = GETDATE() ,CARRYOUT_USER_ID = #{carryoutUserId}
CARRYOUT_STATUS = 'P' ,WH_CARRYOUT_DATE = NULL ,CARRYOUT_USER_ID = NULL
WHERE OD_JOB_NO IN (#{item.odJobNo})

