/* MobEcodMapper.selectLocationList : 모바일 로케이션 조회 */ SELECT CODE AS WH_LOCATION
,${userLangMobile} AS WH_LOCATION_NM
,NAME_${userLanguage} AS WH_LOCATION_NM
FROM TB_SMS_CODE_DETAIL WHERE 1=1 AND USE_YN = 'Y' AND GROUP_CODE = 'WH_LOCATION' AND ENT_CODE = #{entCode}
AND CODE = LTRIM(RTRIM(#{hblNo}))

