		/* MobEcodMapper.inventorySave : 모바일 재고등록 */			
		UPDATE odAdd SET
		    WH_LOCATION = #{whLocation} 

			,STOCK_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())


			,STOCK_DATE_TIME = NULL

		    ,STOCK_USER_ID = #{stockUserId}
		    ,STOCK_YN = #{stockYn}


    	FROM TB_ECM_OD od
		INNER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO
		WHERE od.HBL_NO = LTRIM(RTRIM(#{hblNo}))

/* MobEcodMapper.insertOrderMulti : 멀티등록 */			
INSERT INTO TB_ECM_OD_MULTI(
	OD_JOB_NO
	,SEQ_NO_ID
	,DELIVERY_NO
	,DELIVERY_CODE
	,PAYMENT_GUBN
	,PIECES
	,DIM_WIDTH
	,DIM_LENGTH
	,DIM_HEIGHT
	,VWT
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
)VALUES(
   #{odJobNo}
    ,(SELECT ISNULL(MAX(SEQ_NO_ID), 0) + 1 FROM TB_ECM_OD_MULTI WHERE OD_JOB_NO = #{odJobNo})
    ,#{deliveryNo}
	,#{deliveryCode}
	,#{paymentGubn}
    ,#{pieces}
    ,#{dimWidth}
    ,#{dimLength}
    ,#{dimHeight}
    ,#{vwt}
    ,#{registerUserId}
    ,DATEADD(HOUR, ${gmtTime}, GETDATE())
)

/* MobEcodMapper.updateOrderMulti : 멀티등록 update*/			
UPDATE TB_ECM_OD_MULTI
SET	DELIVERY_CODE = #{deliveryCode}

	,DELIVERY_NO_CHANGED = #{deliveryNoChanged}


	,PAYMENT_GUBN = #{paymentGubn}

	,PIECES = #{pieces}
	,DIM_WIDTH = #{dimWidth}
	,DIM_LENGTH = #{dimLength}
	,DIM_HEIGHT = #{dimHeight}
	,VWT = #{vwt}
	,REGISTER_USER_ID = #{registerUserId}
	,REGISTER_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
WHERE OD_JOB_NO = #{odJobNo}
    AND SEQ_NO_ID = #{seqNoId}

/* MobEcodMapper.deleteOrderMulti : 멀티등록 delete*/		

	DELETE FROM TB_ECM_OD_MULTI
	WHERE OD_JOB_NO = #{odJobNo}


	DELETE FROM TB_ECM_OD_MULTI
	WHERE OD_JOB_NO = (SELECT TOP 1 OD_JOB_NO FROM TB_ECM_OD WHERE ENT_CODE = #{entCode} AND HBL_NO = LTRIM(RTRIM(#{hblNo})) ORDER BY PO_DATE DESC)

/* MobEcodMapper.updateOrderReceiptMulti : 멀티등록 인계정보 update*/		
UPDATE TB_ECM_OD_MULTI SET
	DELIVERER_USER_ID = #{recipientUserId}
	,RECIPIENT_NAME = #{recipientName}

	,DELIVERY_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())
  	,RECEIPT_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())


	,DELIVERY_DATE = NULL
  	,RECEIPT_DATE = NULL



WHERE OD_JOB_NO = #{odJobNo}


WHERE OD_JOB_NO = (SELECT TOP 1 OD_JOB_NO FROM TB_ECM_OD WHERE ENT_CODE = #{entCode} AND HBL_NO = LTRIM(RTRIM(#{hblNo})) ORDER BY PO_DATE DESC)

/* MobEcodMapper.multiBatchDelete : 멀티등록 일괄등록 전 삭제 */
DELETE FROM TB_ECM_OD_MULTI
WHERE OD_JOB_NO IN (#{item.odJobNo})

/* MobEcodMapper.saveReceiptList2 : 인계정보 저장*/	
UPDATE TB_ECM_OD_ADDITIONAL SET
	CARRYOUT_USER_ID = #{recipientUserId}

		,WH_CARRYOUT_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())


		,WH_CARRYOUT_DATE = NULL



		WHERE OD_JOB_NO IN (#{item.odJobNo})


		WHERE OD_JOB_NO = #{odJobNo}

