/* MobEcodMapper.selectOrderDetailByCarryoutList : 출고처리 리스트 조회 */ SELECT od.OD_JOB_NO ,od.HBL_NO ,od.PIECES ,od.GWT ,odAdd.CARRYIN_DATE ,CASE WHEN pod.POD_STATUS = 'ECM280' THEN 'Y' ELSE 'N' END AS CARRYOUT_YN ,CASE WHEN (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0 THEN 'Y' ELSE 'N' END AS HOLD_YN FROM TB_ECM_OD od LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO LEFT OUTER JOIN TB_ECM_POD_03 pod ON od.OD_JOB_NO = pod.OD_JOB_NO AND pod.POD_STATUS = 'ECM280' WHERE od.ENT_CODE = #{entCode} AND od.PIECES > 0 AND (od.CD_TYPE = 'N' OR od.CD_TYPE = 'B' OR odAdd.DROP_YN = 'Y') AND od.DEST_CODE = #{destCode} AND odAdd.CARRYIN_DATE IS NOT NULL AND odAdd.CLEARANCE_DATE IS NOT NULL
AND od.BOUND_TYPE >= #{srchBoundType}
AND od.AR_DATE >= #{srchStartDate}
AND od.AR_DATE <= #{srchEndDate}
AND WH_CARRYOUT_DATE IS NULL AND CARRYOUT_USER_ID IS NULL
AND WH_CARRYOUT_DATE IS NOT NULL AND CARRYOUT_USER_ID IS NOT NULL

/* MobEcodMapper.selectMultiOrderList : 화물 일괄 조회(송장번호) */ SELECT mu.DELIVERY_NO ,od.OD_JOB_NO ,mu.SEQ_NO_ID ,od.PIECES, od.GWT ,(CASE WHEN 'ECM280' IN (SELECT POD_STATUS FROM TB_ECM_POD_03 po WHERE od.ENT_CODE = po.ENT_CODE AND od.OD_JOB_NO = po.OD_JOB_NO) THEN 'Y' ELSE 'N' END) AS ECM280YN ,CASE WHEN (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0 THEN 'Y' ELSE 'N' END AS HOLD_YN ,od.PO_DATE FROM TB_ECM_OD od LEFT OUTER JOIN TB_ECM_OD_MULTI mu ON od.OD_JOB_NO = mu.OD_JOB_NO WHERE od.ENT_CODE = #{entCode} AND mu.DELIVERY_NO = LTRIM(RTRIM(#{hblNo}))
AND od.OD_JOB_NO = #{odJobNo}
AND od.DEST_CODE = #{destCode}
AND od.AR_DATE > DATEADD(DD, -90, GETDATE())

