/* MobEcodMapper.updateMultiOrderDeliveryMul : 변경배송사 업데이트(멀티중량화물) */	
	UPDATE TB_ECM_OD_MULTI 
	SET
	    DELIVERY_CODE = #{deliveryCode}      
	WHERE OD_JOB_NO = #{odJobNo}
    AND SEQ_NO_ID = #{seqNoId}

/* MobEcodMapper.deleteCaseOrderDelivery : 건별 그리드 delete*/		
	DELETE FROM TB_ECM_OD_MULTI
	WHERE OD_JOB_NO = #{odJobNo}

/* MobEcodMapper.saveCaseOrderDelivery : 건별 변경송장번호 등록 */			
INSERT INTO TB_ECM_OD_MULTI(
	OD_JOB_NO
	,SEQ_NO_ID
	,DELIVERY_NO
	,DELIVERY_NO_CHANGED
	,DELIVERY_CODE
	,PAYMENT_GUBN
	,DELIVERY_FEE
	,PIECES
	,DIM_WIDTH
	,DIM_LENGTH
	,DIM_HEIGHT
	,VWT
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
)VALUES(
    #{odJobNo}
    ,(SELECT ISNULL(MAX(SEQ_NO_ID), 0) + 1 FROM TB_ECM_OD_MULTI WHERE OD_JOB_NO = #{odJobNo})
    ,#{notChkBl}
    ,#{deliveryNoChanged}
	,#{deliveryCodeChange}
	,#{paymentGubn}
	,#{deliveryFee}
	,#{pieces}
	,#{dimWidth}
	,#{dimLength}
	,#{dimHeight}
	,#{vwt}
    ,#{registerUserId}
    ,DATEADD(HOUR, ${gmtTime}, GETDATE())
)

	/* MobEcodMapper.updateCaseOrderDelivery : 건별 변경송장번호 멀티 업데이트 */
	UPDATE TB_ECM_OD_MULTI SET
        DELIVERY_CODE        = #{deliveryCodeChange}
		 ,PAYMENT_GUBN         = #{paymentGubn}
		 ,DELIVERY_FEE         = #{deliveryFee}
		 ,PIECES               = #{pieces}
		 ,DIM_WIDTH            = #{dimWidth}
		 ,DIM_LENGTH           = #{dimLength}
		 ,DIM_HEIGHT           = #{dimHeight}
		 ,VWT                  = #{vwt}
	WHERE OD_JOB_NO = #{odJobNo}
	AND DELIVERY_NO  = #{notChkBl}
